import{_ as l,r as a,o as p,c as o,e as s,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Partial Field - October CMS - 3.x","titleTemplate":false,"description":"Form UI","frontmatter":{"subtitle":"Form UI","shortname":"Partial"},"headers":[{"level":2,"title":"Accessing Variables","slug":"accessing-variables","link":"#accessing-variables","children":[]},{"level":2,"title":"Using View Templates","slug":"using-view-templates","link":"#using-view-templates","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/element/form/ui-partial.md","filePath":"3.x/element/form/ui-partial.md"}'),r={name:"3.x/element/form/ui-partial.md"};function d(u,e,h,m,k,g){const n=a("pre-heading"),t=a("post-heading");return p(),o("div",null,[s(n),e[0]||(e[0]=i("h1",null,"Partial Field",-1)),s(t),e[1]||(e[1]=c(`<p>The <code>partial</code> UI element renders a partial, the <code>path</code> value can refer to a partial view file otherwise the field name is used as the partial name.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_content
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>path</strong></td><td>path to a <a href="./../../extend/system/views.html">partial view file</a> or <a href="./../../extend/services/response-view.html">view template code</a>, defaults to the field name with <strong>field_</strong> as a prefix.</td></tr></tbody></table></div><p>When the <code>path</code> is set to an unqualified file name (a file name without a directory path and extension), the source path is determined to be in the model or controller directories. The following example will check for the partial file at <strong>../models/mymodel/_field_for_content.php</strong> or <strong>../controllers/mycontroller/_field_for_content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_for_content
</code></pre></div><p>You may specify a fully qualified <code>path</code> to access partials outside the model or controller directories. This can be useful for sharing partials between definitions.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_field_content.php
</code></pre></div><h2 id="accessing-variables"><a href="#accessing-variables" class="header-anchor">#</a> Accessing Variables</h2><p>The following variables are available inside the partial when it is rendered.</p><ul><li><code>$value</code> is the current field value, if found.</li><li><code>$model</code> is the <a href="./../../extend/system/models.html">model used</a> for the field</li><li><code>$field</code> is the configured class object <code>Backend\\Classes\\FormField</code></li></ul><p>Here is an some example contents of the <strong>_field_content.php</strong> file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">label</span> <span class="token delimiter important">?&gt;</span></span> is active<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="using-view-templates"><a href="#using-view-templates" class="header-anchor">#</a> Using View Templates</h2><p>You may pass a view template code as the <code>path</code> to access view service templates inside the plugin. The following code would be found at the path <strong>plugins/acme/blog/views/formfields/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><p>You may also place a partial in the app directory, for example, <strong>app/views/formfields/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> app<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><div class="custom-block tip"><p>The path must contain the <code>::</code> characters to activate the view service.</p></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./ui-hint.html">Hint Form UI</a></li><li><a href="./../../extend/system/views.html">Rendering Controller Views</a></li><li><a href="./../../extend/services/response-view.html">Response &amp; View Service</a></li></ul></div>`,21))])}const y=l(r,[["render",d]]);export{v as __pageData,y as default};
